"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { formatDateReadable } from "@/lib/utils/date-format";
import { ElegantBackground } from "@/components/ui/elegant-background";
import { Button } from "@/components/ui/button";
import { Loader2, Award, Calendar, Hash, School, Globe, FileText, Users, Layers, Download, Share2, Search, AlertTriangle, CheckCircle } from "lucide-react";
import { motion } from "framer-motion";

type CertificateData = {
  certificate_id: string;
  participant_name: string;
  school: string;
  certificate_type: string;
  event: string | null;
  event_code: string | null;
  date_issued: string;
  status: string;
  pdf_available: boolean;
  pdf_download_url: string | null;
  country?: string;
  committee?: string;
  segment?: string;
  team_name?: string;
  [key: string]: any;
};

export default function CertificateVerifyPage({
  params,
}: {
  params: Promise<{ certificateId: string }>;
}) {
  const router = useRouter();
  const [certificateId, setCertificateId] = useState<string>("");
  const [loading, setLoading] = useState(true);
  const [certificate, setCertificate] = useState<CertificateData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [valid, setValid] = useState<boolean | null>(null);
  const [revoked, setRevoked] = useState(false);
  const [revokedInfo, setRevokedInfo] = useState<{
    revoked_at: string;
    revoked_reason: string;
  } | null>(null);

  useEffect(() => {
    async function fetchCertificate() {
      const resolvedParams = await params;
      const id = resolvedParams.certificateId;
      setCertificateId(id);
      setLoading(true);

      try {
        const response = await fetch(`/api/verify/${id}`);
        const data = await response.json();

        if (data.valid) {
          setValid(true);
          setCertificate(data.certificate);
          setRevoked(false);
        } else if (data.status === "revoked") {
          setValid(false);
          setRevoked(true);
          setRevokedInfo({
            revoked_at: data.revoked_at,
            revoked_reason: data.revoked_reason,
          });
          setCertificate(data.certificate);
        } else {
          setValid(false);
          setError(data.error || "Certificate not found");
        }
      } catch (err: any) {
        setValid(false);
        setError(err.message || "Failed to verify certificate");
      } finally {
        setLoading(false);
      }
    }

    fetchCertificate();
  }, [params]);

  if (loading) {
    return (
      <div className="min-h-screen relative overflow-hidden flex items-center justify-center">
        <ElegantBackground variant="section" />
        <div className="relative z-10 flex flex-col items-center gap-4">
          <div className="relative">
            <div className="w-12 h-12 border-4 border-accent-gold/20 border-t-accent-gold rounded-full animate-spin" />
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="w-2 h-2 bg-accent-gold rounded-full animate-pulse" />
            </div>
          </div>
          <p className="text-accent-gold/70 font-medium animate-pulse">Verifying certificate...</p>
        </div>
      </div>
    );
  }

  if (error && !certificate) {
    return (
      <div className="min-h-screen relative overflow-hidden flex items-center justify-center p-4">
        <ElegantBackground variant="section" />
        <div className="relative z-10 max-w-md w-full bg-forest-900/40 border border-destructive/30 backdrop-blur-md rounded-xl p-8 text-center">
          <div className="mb-6 flex justify-center">
            <div className="p-4 bg-destructive/10 rounded-full border border-destructive/20">
              <AlertTriangle className="h-8 w-8 text-destructive" />
            </div>
          </div>
          <h1 className="text-2xl font-bold text-foreground mb-2">
            Certificate Not Found
          </h1>
          <p className="text-muted-foreground mb-8">{error}</p>
          <Button
            onClick={() => router.push("/certificate-portal")}
            className="w-full bg-accent-gold hover:bg-accent-gold/90 text-forest-950"
          >
            Try Another ID
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen relative overflow-hidden py-24">
      <ElegantBackground variant="section" />
      
      <div className="relative z-10 max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-12"
        >
          <h1 className="font-display text-4xl md:text-5xl font-bold text-foreground mb-4">
            Certificate <span className="text-accent-gold">Verification</span>
          </h1>
          <p className="text-lg text-muted-foreground">
            Verify authenticity and view certificate details
          </p>
        </motion.div>

        {/* Main Certificate Card */}
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="relative bg-forest-900/40 border border-accent-gold/20 rounded-2xl p-6 md:p-10 backdrop-blur-md shadow-xl overflow-hidden"
        >
          {/* Decorative background elements */}
          <div className="absolute top-0 right-0 w-64 h-64 bg-accent-gold/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />

          {/* Status Badge */}
          <div className="mb-8 flex justify-center relative z-10">
            {revoked ? (
              <div className="inline-flex items-center gap-2 rounded-full border border-destructive/40 bg-destructive/10 px-6 py-2 backdrop-blur-sm">
                <AlertTriangle className="h-4 w-4 text-destructive animate-pulse" />
                <span className="font-semibold text-destructive">
                  Certificate Revoked
                </span>
              </div>
            ) : valid ? (
              <div className="inline-flex items-center gap-2 rounded-full border border-green-500/40 bg-green-500/10 px-6 py-2 backdrop-blur-sm">
                <CheckCircle className="h-4 w-4 text-green-500" />
                <span className="font-semibold text-green-500">
                  Certificate Verified
                </span>
              </div>
            ) : null}
          </div>

          {/* Revocation Notice */}
          {revoked && revokedInfo && (
            <div className="mb-8 rounded-xl border border-destructive/30 bg-destructive/5 p-6 relative z-10">
              <div className="flex items-start gap-4">
                <AlertTriangle className="h-6 w-6 text-destructive flex-shrink-0" />
                <div>
                  <h3 className="font-semibold text-destructive mb-2">
                    Certificate Revocation Notice
                  </h3>
                  <div className="space-y-1 text-sm text-muted-foreground">
                    <p>
                      <span className="font-medium text-foreground">Revoked on:</span>{" "}
                      {formatDateReadable(revokedInfo.revoked_at)}
                    </p>
                    <p>
                      <span className="font-medium text-foreground">Reason:</span>{" "}
                      {revokedInfo.revoked_reason || "Not specified"}
                    </p>
                  </div>
                  <p className="text-xs text-muted-foreground mt-4">
                    This certificate is no longer valid. For inquiries, contact the issuing organization.
                  </p>
                </div>
              </div>
            </div>
          )}

          {certificate && (
            <div className="space-y-8 relative z-10">
              {/* Primary Info */}
              <div className="border-b border-accent-gold/20 pb-8 text-center md:text-left">
                <p className="text-xs uppercase tracking-[0.2em] text-accent-gold mb-3">
                  Certificate Holder
                </p>
                <h2 className="font-display text-3xl md:text-4xl font-bold text-foreground mb-4">
                  {certificate.participant_name}
                </h2>
                <div className="flex flex-wrap justify-center md:justify-start gap-6 text-sm">
                  <div className="flex items-center gap-2">
                    <School className="h-4 w-4 text-accent-gold" />
                    <span className="text-muted-foreground">From</span>
                    <span className="text-foreground font-medium">{certificate.school}</span>
                  </div>
                  {certificate.country && (
                    <div className="flex items-center gap-2">
                      <Globe className="h-4 w-4 text-accent-gold" />
                      <span className="text-muted-foreground">Country</span>
                      <span className="text-foreground font-medium">{certificate.country}</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Certificate Details Grid */}
              <div className="grid gap-6 md:grid-cols-3">
                <div className="bg-forest-950/30 rounded-xl border border-accent-gold/10 p-5">
                  <div className="flex items-center gap-2 mb-2">
                    <Award className="h-4 w-4 text-accent-gold" />
                    <p className="text-xs uppercase tracking-wider text-muted-foreground">
                      Type
                    </p>
                  </div>
                  <p className="text-lg font-semibold text-foreground">
                    {certificate.certificate_type}
                  </p>
                </div>

                <div className="bg-forest-950/30 rounded-xl border border-accent-gold/10 p-5">
                  <div className="flex items-center gap-2 mb-2">
                    <Calendar className="h-4 w-4 text-accent-gold" />
                    <p className="text-xs uppercase tracking-wider text-muted-foreground">
                      Date Issued
                    </p>
                  </div>
                  <p className="text-lg font-semibold text-foreground">
                    {formatDateReadable(certificate.date_issued)}
                  </p>
                </div>

                <div className="bg-forest-950/30 rounded-xl border border-accent-gold/10 p-5">
                  <div className="flex items-center gap-2 mb-2">
                    <Hash className="h-4 w-4 text-accent-gold" />
                    <p className="text-xs uppercase tracking-wider text-muted-foreground">
                      Certificate ID
                    </p>
                  </div>
                  <p className="text-sm font-mono text-accent-gold break-all">
                    {certificate.certificate_id}
                  </p>
                </div>
              </div>

              {/* Event Info */}
              {certificate.event && (
                <div className="bg-gradient-to-r from-accent-gold/5 to-transparent rounded-xl border border-accent-gold/10 p-6">
                  <p className="text-xs uppercase tracking-wider text-accent-gold mb-2">
                    Event
                  </p>
                  <h3 className="text-xl font-bold text-foreground mb-1">
                    {certificate.event}
                  </h3>
                  {certificate.event_code && (
                    <p className="text-sm text-muted-foreground">
                      Event Code: <span className="text-foreground">{certificate.event_code}</span>
                    </p>
                  )}
                </div>
              )}

              {/* Additional Metadata */}
              {(certificate.level || certificate.committee || certificate.segment || certificate.team_name) && (
                <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
                  {certificate.level && (
                    <div className="bg-forest-950/30 rounded-xl border border-accent-gold/10 p-4">
                      <div className="flex items-center gap-2 mb-1">
                        <Layers className="h-3 w-3 text-accent-gold" />
                        <p className="text-xs uppercase tracking-wider text-muted-foreground">Level</p>
                      </div>
                      <p className="text-foreground font-medium capitalize">{certificate.level}</p>
                    </div>
                  )}
                  {certificate.committee && (
                    <div className="bg-forest-950/30 rounded-xl border border-accent-gold/10 p-4">
                      <div className="flex items-center gap-2 mb-1">
                        <Users className="h-3 w-3 text-accent-gold" />
                        <p className="text-xs uppercase tracking-wider text-muted-foreground">Committee</p>
                      </div>
                      <p className="text-foreground font-medium">{certificate.committee}</p>
                    </div>
                  )}
                  {certificate.segment && (
                    <div className="bg-forest-950/30 rounded-xl border border-accent-gold/10 p-4">
                      <div className="flex items-center gap-2 mb-1">
                        <FileText className="h-3 w-3 text-accent-gold" />
                        <p className="text-xs uppercase tracking-wider text-muted-foreground">Segment</p>
                      </div>
                      <p className="text-foreground font-medium">{certificate.segment}</p>
                    </div>
                  )}
                  {certificate.team_name && (
                    <div className="bg-forest-950/30 rounded-xl border border-accent-gold/10 p-4">
                      <div className="flex items-center gap-2 mb-1">
                        <Users className="h-3 w-3 text-accent-gold" />
                        <p className="text-xs uppercase tracking-wider text-muted-foreground">Team</p>
                      </div>
                      <p className="text-foreground font-medium">{certificate.team_name}</p>
                    </div>
                  )}
                </div>
              )}

              {/* Actions */}
              <div className="flex flex-wrap gap-4 pt-6 border-t border-accent-gold/20">
                <Button
                  onClick={() => {
                    navigator.clipboard.writeText(
                      `${window.location.origin}/certificate-portal/${certificate.certificate_id}`
                    );
                    // You might want to add a toast here
                    alert("Certificate link copied to clipboard!");
                  }}
                  variant="outline"
                  className="flex-1 border-accent-gold/30 text-accent-gold hover:bg-accent-gold/10"
                >
                  <Share2 className="h-4 w-4 mr-2" />
                  Share
                </Button>
                
                {certificate.pdf_available && certificate.pdf_download_url && (
                  <Button
                    onClick={() => window.open(certificate.pdf_download_url!, "_blank")}
                    className="flex-1 bg-accent-gold hover:bg-accent-gold/90 text-forest-950"
                  >
                    <Download className="h-4 w-4 mr-2" />
                    Download PDF
                  </Button>
                )}
                
                <Button
                  onClick={() => router.push("/certificate-portal")}
                  variant="ghost"
                  className="flex-1 hover:bg-forest-900/50"
                >
                  <Search className="h-4 w-4 mr-2" />
                  Verify Another
                </Button>
              </div>
            </div>
          )}
        </motion.div>

        {/* Footer Help */}
        <div className="text-center mt-12">
          <p className="text-sm text-muted-foreground">
            Need help? Contact{" "}
            <a
              href="mailto:intlglobalaffairscouncil@gmail.com"
              className="text-accent-gold hover:underline font-medium transition"
            >
              IGAC Support
            </a>
          </p>
        </div>
      </div>
    </div>
  );
}
